import math
from collections import defaultdict

img=Image.open('/app/chess_board.png')
size=img.size[0]
sq=size//8
pix=img.load()
light=(240,217,181)
dark=(181,136,99)

def dist(a,b):
    return sum((a[i]-b[i])**2 for i in range(3))**0.5

# gather pieces info
pieces=[]
for r in range(8):
    for c in range(8):
        x0=c*sq; y0=r*sq
        colors=[]
        for y in range(y0+5,y0+sq-5):
            for x in range(x0+5,x0+sq-5):
                p=pix[x,y]
                if dist(p,light)<20 or dist(p,dark)<20:
                    continue
                colors.append(p)
        count=len(colors)
        if count>100:
            avg=sum((p[0]+p[1]+p[2]) for p in colors)/count
            color='w' if avg>400 else 'b'
            pieces.append((r,c,color))


def signature(r,c):
    x0=c*sq; y0=r*sq
    grid=[]
    for gy in range(16):
        row=[]
        for gx in range(16):
            cnt=0
            for y in range(y0+gy*sq//16, y0+(gy+1)*sq//16):
                for x in range(x0+gx*sq//16, x0+(gx+1)*sq//16):
                    p=pix[x,y]
                    if dist(p,light)<20 or dist(p,dark)<20:
                        continue
                    cnt+=1
            row.append(1 if cnt>5 else 0)
        grid.append(row)
    return tuple([v for row in grid for v in row])

# cluster signatures by color
sig_to_id={}
next_id={'w':1,'b':1}
clusters=defaultdict(list)

for r,c,color in pieces:
    sig=signature(r,c)
    key=(color,sig)
    if key not in sig_to_id:
        sig_to_id[key]=f"{color}{next_id[color]}"
        next_id[color]+=1
    clusters[sig_to_id[key]].append((r,c))

# board representation
board=[['.' for _ in range(8)] for _ in range(8)]
for r,c,color in pieces:
    sig=signature(r,c)
    id=sig_to_id[(color,sig)]
    board[r][c]=id

for r in range(8):
    print(8-r, board[r])
print('  a b c d e f g h')
print('clusters:', clusters)
