from PIL import Image
import math
from collections import defaultdict

img=Image.open('/app/chess_board.png')
size=img.size[0]
sq=size//8
pix=img.load()
light=(240,217,181)
dark=(181,136,99)

def dist(a,b):
    return sum((a[i]-b[i])**2 for i in range(3))**0.5

# detect pieces positions and color (white/black) as before
pieces=[]
for r in range(8):
    for c in range(8):
        x0=c*sq; y0=r*sq
        colors=[]
        for y in range(y0+5,y0+sq-5):
            for x in range(x0+5,x0+sq-5):
                p=pix[x,y]
                if dist(p,light)<20 or dist(p,dark)<20:
                    continue
                colors.append(p)
        count=len(colors)
        if count>100:
            avg=sum((p[0]+p[1]+p[2]) for p in colors)/count
            color='w' if avg>400 else 'b'
            pieces.append((r,c,color))

# compute mask signature 32x32

def mask_sig(r,c):
    x0=c*sq; y0=r*sq
    sig=[]
    for gy in range(32):
        for gx in range(32):
            x=int(x0 + (gx+0.5)*sq/32)
            y=int(y0 + (gy+0.5)*sq/32)
            p=pix[x,y]
            if dist(p,light)<20 or dist(p,dark)<20:
                sig.append(0)
            else:
                sig.append(1)
    return sig

# cluster by exact signature (as earlier)
clusters=defaultdict(list)
for r,c,color in pieces:
    sig=tuple(mask_sig(r,c))
    clusters[(color,sig)].append((r,c))

# assign IDs
idmap={}
next_id={'w':1,'b':1}
for key in clusters:
    color=key[0]
    idmap[key]=f"{color}{next_id[color]}"; next_id[color]+=1

# compute representative signature for each id
sigs={idmap[key]: key[1] for key in clusters}
positions={idmap[key]: clusters[key] for key in clusters}

# compute similarity between all pairs (white vs black)
white_ids=[i for i in sigs if i.startswith('w')]
black_ids=[i for i in sigs if i.startswith('b')]

def jaccard(sig1,sig2):
    # sigs are tuples of 0/1
    inter=sum(1 for a,b in zip(sig1,sig2) if a==1 and b==1)
    union=sum(1 for a,b in zip(sig1,sig2) if a==1 or b==1)
    return inter/union if union else 0

# compute best match for each white id
for wid in white_ids:
    best=None
    for bid in black_ids:
        score=jaccard(sigs[wid], sigs[bid])
        if best is None or score>best[1]:
            best=(bid,score)
    print('white',wid,'best black',best)

# also compute similarity between white pieces themselves to identify same types? (maybe w1 vs w2)
print('\nwhite-white similarity')
for i in range(len(white_ids)):
    for j in range(i+1,len(white_ids)):
        w1=white_ids[i]; w2=white_ids[j]
        score=jaccard(sigs[w1],sigs[w2])
        if score>0.8:
            print(w1,w2,score)

print('\nblack-black similarity')
for i in range(len(black_ids)):
    for j in range(i+1,len(black_ids)):
        b1=black_ids[i]; b2=black_ids[j]
        score=jaccard(sigs[b1],sigs[b2])
        if score>0.8:
            print(b1,b2,score)

# output ids with positions
print('\npositions')
for id, pos in positions.items():
    print(id,pos)
