import math
from collections import defaultdict

img=Image.open('/app/chess_board.png')
size=img.size[0]
sq=size//8
pix=img.load()
light=(240,217,181)
dark=(181,136,99)

def dist(a,b):
    return sum((a[i]-b[i])**2 for i in range(3))**0.5

# detect pieces
pieces=[]
for r in range(8):
    for c in range(8):
        x0=c*sq; y0=r*sq
        colors=[]
        for y in range(y0+5,y0+sq-5):
            for x in range(x0+5,x0+sq-5):
                p=pix[x,y]
                if dist(p,light)<20 or dist(p,dark)<20:
                    continue
                colors.append(p)
        count=len(colors)
        if count>100:
            avg=sum((p[0]+p[1]+p[2]) for p in colors)/count
            color='w' if avg>400 else 'b'
            pieces.append((r,c,color))

# mask signature

def mask_sig(r,c):
    x0=c*sq; y0=r*sq
    sig=[]
    for gy in range(32):
        for gx in range(32):
            x=int(x0 + (gx+0.5)*sq/32)
            y=int(y0 + (gy+0.5)*sq/32)
            p=pix[x,y]
            sig.append(0 if dist(p,light)<20 or dist(p,dark)<20 else 1)
    return sig

# jaccard

def jaccard(sig1,sig2):
    inter=0; union=0
    for a,b in zip(sig1,sig2):
        if a or b:
            union+=1
            if a and b:
                inter+=1
    return inter/union if union else 0

# compute similarity across all pieces (white vs black)
white=[(r,c,color,mask_sig(r,c)) for r,c,color in pieces if color=='w']
black=[(r,c,color,mask_sig(r,c)) for r,c,color in pieces if color=='b']

# find pair matches with similarity >0.9
pairs=[]
for wr,wc,_,wsig in white:
    for br,bc,_,bsig in black:
        score=jaccard(wsig,bsig)
        if score>0.9:
            pairs.append(((wr,wc),(br,bc),score))

print('high similarity pairs',pairs)

# compute best black match for each white
for wr,wc,_,wsig in white:
    best=None
    for br,bc,_,bsig in black:
        score=jaccard(wsig,bsig)
        if best is None or score>best[2]:
            best=(br,bc,score)
    print('white', (wr,wc),'best',best)

